-- Migration: Year 2 - Hematology Pathology MCQs Part 1 (1-40)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Hematology Pathology', 'hematology-pathology', 3, 2, 61)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- ANEMIA: OVERVIEW & LAB CLASSIFICATION (1-10)
    (v_topic_id, 'Anemia in an adult male is defined by a hemoglobin below what threshold?', '["Below 15 g/dL", "Below 13.5 g/dL", "Below 12 g/dL", "Below 11 g/dL"]', 1, 'In adult males, Hgb <13.5 g/dL defines anemia. In adult females, the threshold is <12 g/dL.'),
    (v_topic_id, 'The most useful initial test to classify the type of anemia is?', '["Reticulocyte count", "Peripheral blood smear", "Mean Corpuscular Volume (MCV)", "Serum ferritin"]', 2, 'MCV classifies anemia as microcytic (<80 fL), normocytic (80-100 fL), or macrocytic (>100 fL), guiding the differential diagnosis.'),
    (v_topic_id, 'A corrected reticulocyte count below 2% in an anemic patient indicates what pathophysiology?', '["Increased peripheral destruction of RBCs", "Hypoproliferative bone marrow failure to produce RBCs", "Intravascular hemolysis", "Splenic sequestration"]', 1, 'A low corrected reticulocyte count (<2%) means the marrow is not responding adequately, pointing to hypoproliferative causes: iron deficiency, B12/folate deficiency, aplastic anemia, or renal failure.'),
    (v_topic_id, 'Which RBC morphology finding on peripheral smear indicates active hemolysis and a compensatory marrow response?', '["Hypersegmented neutrophils", "Polychromasia (bluish RBCs = reticulocytes)", "Ring sideroblasts", "Howell-Jolly bodies"]', 1, 'Polychromasia reflects reticulocytosis. Reticulocytes are larger, bluish RBCs that still contain residual RNA. Their presence confirms the marrow is actively responding.'),
    (v_topic_id, 'Schistocytes (fragmented RBCs) on peripheral smear are the hallmark of which category of anemia?', '["Iron deficiency anemia", "Megaloblastic anemia", "Microangiopathic hemolytic anemia (MAHA)", "Aplastic anemia"]', 2, 'Schistocytes form when RBCs are mechanically sheared by fibrin strands in small vessels. Classic MAHA causes: TTP, HUS, DIC, malignant hypertension, and prosthetic heart valves.'),
    (v_topic_id, 'In a patient with chronic anemia and a low reticulocyte count, which combination of findings on peripheral smear would suggest megaloblastic anemia?', '["Schistocytes and spherocytes", "Hypersegmented neutrophils and macro-ovalocytes", "Target cells and basophilic stippling", "Bite cells and Heinz bodies"]', 1, 'Megaloblastic anemia (B12 or folate deficiency) causes impaired DNA synthesis in all rapidly dividing cells. Hallmarks: macro-ovalocytes and hypersegmented neutrophils (5+ nuclear lobes).'),
    (v_topic_id, 'Which of the following is the correct order of lab abnormalities as iron deficiency anemia progresses from earliest to latest?', '["Anemia → low ferritin → low serum iron", "Low ferritin → low serum iron, high TIBC → microcytic anemia", "Microcytic anemia → low ferritin → low serum iron", "High TIBC → anemia → low ferritin"]', 1, 'Iron stores (ferritin) are depleted first. Then serum iron falls and TIBC rises (more empty transferrin). Finally, when iron is critically low, hemoglobin synthesis drops, causing anemia.'),
    (v_topic_id, 'Which lab pattern correctly identifies iron deficiency anemia (IDA)?', '["Low serum iron, high TIBC, low ferritin", "Low serum iron, low TIBC, high ferritin", "High serum iron, high TIBC, low ferritin", "Normal serum iron, normal TIBC, low ferritin"]', 0, 'IDA: low serum iron (depleted supply) + high TIBC (more empty transferrin seeking iron) + low ferritin (stores exhausted). This triad is diagnostic.'),
    (v_topic_id, 'Target cells (codocytes) are seen in which of the following conditions?', '["Hereditary spherocytosis and G6PD deficiency", "Iron deficiency, thalassemia, liver disease, and post-splenectomy", "Only in hemoglobin C disease", "Only in sickle cell disease"]', 1, 'Target cells form when there is excess RBC membrane relative to hemoglobin content. Classic causes: thalassemia, IDA, liver disease (excess cholesterol in membrane), hemoglobin C disease, and post-splenectomy.'),
    (v_topic_id, 'Basophilic stippling of RBCs on peripheral smear is classically associated with which two conditions?', '["G6PD deficiency and hereditary spherocytosis", "Lead poisoning and sideroblastic anemia", "B12 deficiency and folate deficiency", "TTP and HUS"]', 1, 'Basophilic stippling = aggregated ribosomes in RBCs. Seen classically in lead poisoning (lead inhibits pyrimidine 5-nucleotidase, preventing ribosome breakdown) and sideroblastic anemia.'),

    -- IRON DEFICIENCY ANEMIA (11-22)
    (v_topic_id, 'A 2-year-old child is brought in for pallor and irritability. Diet consists mostly of cow milk. Labs show Hgb 8 g/dL and MCV 65. What is the most likely diagnosis?', '["Beta-thalassemia minor", "Iron deficiency anemia from dietary insufficiency and occult GI loss", "Anemia of chronic disease", "Lead poisoning"]', 1, 'Cow milk is low in iron and can irritate the gut, causing occult GI blood loss. Toddlers drinking excessive cow milk at the expense of iron-rich foods is the classic pediatric IDA scenario.'),
    (v_topic_id, 'A 35-year-old woman has fatigue, pica (craving ice), koilonychia, and angular cheilitis. Labs: Hgb 9, MCV 72, low ferritin. Diagnosis?', '["Folate deficiency", "Iron deficiency anemia", "Vitamin B12 deficiency", "Hemolytic anemia"]', 1, 'Classic IDA manifestations: pica (ice/pagophagia, dirt/geophagia), koilonychia (spoon nails), angular cheilitis, glossitis. All result from iron-dependent enzyme deficiencies beyond hemoglobin.'),
    (v_topic_id, 'Plummer-Vinson syndrome consists of which triad?', '["Dysphagia, esophageal varices, iron deficiency", "Iron deficiency anemia, esophageal web (post-cricoid), glossitis", "Iron deficiency, Barrett esophagus, dysphagia", "Macrocytic anemia, glossitis, esophageal cancer"]', 1, 'Plummer-Vinson (Paterson-Kelly): microcytic anemia + post-cricoid esophageal web + glossitis. Associated with increased risk of squamous cell carcinoma of the esophagus.'),
    (v_topic_id, 'The most common cause of iron deficiency anemia in an adult male or postmenopausal woman in a developed country is?', '["Dietary iron insufficiency", "Occult gastrointestinal blood loss (e.g., colon cancer, peptic ulcer)", "Malabsorption from celiac disease", "Intravascular hemolysis"]', 1, 'GI blood loss is the most common cause in adults who are not menstruating. Colon cancer must be excluded in any adult male or postmenopausal woman with new IDA — it is a red flag finding.'),
    (v_topic_id, 'Which test is the MOST sensitive indicator of early iron deficiency before anemia develops?', '["Serum hemoglobin", "MCV", "Serum ferritin", "Peripheral blood smear"]', 2, 'Ferritin reflects stored iron. It falls first, before serum iron, TIBC, or hemoglobin change. A low ferritin is virtually diagnostic of iron deficiency, even in the absence of anemia.'),
    (v_topic_id, 'A patient has low MCV, low serum iron, low ferritin, high TIBC. After 3 months of oral iron therapy, the hemoglobin does not improve. The next step to consider?', '["Increase the iron dose", "Check for non-compliance or malabsorption (celiac disease, H. pylori)", "Switch to folate supplementation", "Perform bone marrow biopsy immediately"]', 1, 'Failure to respond to oral iron should prompt evaluation for: non-compliance, continued blood loss, malabsorption (celiac disease, atrophic gastritis, H. pylori), or wrong diagnosis.'),
    (v_topic_id, 'Iron is absorbed primarily in which part of the GI tract?', '["Stomach", "Duodenum and proximal jejunum", "Terminal ileum", "Colon"]', 1, 'Duodenal enterocytes absorb non-heme iron (Fe3+ reduced to Fe2+ by duodenal cytochrome b / DcytB) and heme iron. Ferroportin exports Fe2+ into blood; hepcidin degrades ferroportin, blocking absorption.'),
    (v_topic_id, 'Hepcidin is the master regulator of iron homeostasis. High hepcidin causes iron deficiency by?', '["Increasing GI iron loss", "Degrading ferroportin on enterocytes and macrophages, blocking iron export into the blood", "Decreasing transferrin synthesis", "Increasing renal iron excretion"]', 1, 'Hepcidin (made by hepatocytes) binds and degrades ferroportin, the only known cellular iron exporter. This traps iron inside enterocytes (preventing absorption) and macrophages (preventing iron recycling).'),
    (v_topic_id, 'In anemia of chronic disease, which cytokine primarily drives hepcidin production, explaining iron sequestration?', '["TNF-alpha", "IL-6", "IL-1", "IFN-gamma"]', 1, 'IL-6 (released during chronic inflammation) is the primary inducer of hepcidin production in the liver. This is the central mechanism of ACD: inflammatory cytokines → high hepcidin → iron trapped → iron-restricted erythropoiesis.'),
    (v_topic_id, 'Which lab pattern correctly identifies anemia of chronic disease (ACD)?', '["Low serum iron, high TIBC, low ferritin", "Low serum iron, low TIBC, normal/high ferritin", "High serum iron, high TIBC, low ferritin", "Normal serum iron, normal ferritin, high TIBC"]', 1, 'ACD: serum iron is low (iron sequestered in macrophages) + TIBC is low (less transferrin synthesized, opposite of IDA) + ferritin is normal or high (iron stored in macrophages). Key distinction from IDA.'),
    (v_topic_id, 'A patient with rheumatoid arthritis has Hgb 10, MCV 80 (normocytic), low serum iron, low TIBC, and ferritin of 180. What is the diagnosis?', '["Iron deficiency anemia", "Anemia of chronic disease", "Sideroblastic anemia", "Aplastic anemia"]', 1, 'This is classic ACD: underlying chronic inflammation (RA) + normocytic (or mildly microcytic) anemia + low Fe + low TIBC + HIGH ferritin. Ferritin >100 essentially rules out IDA as the sole cause.'),
    (v_topic_id, 'How is anemia of chronic disease treated in a patient who is not responsive to treating the underlying disease?', '["Oral iron supplementation alone", "Erythropoiesis-stimulating agents (ESAs) like epoetin alfa, especially in renal or cancer-related ACD", "Blood transfusions for all patients", "IV iron alone"]', 1, 'ESAs (recombinant EPO) stimulate erythropoiesis and can overcome the blunted EPO response in ACD. IV iron + ESA is used in CKD and chemotherapy-related anemia.'),

    -- SIDEROBLASTIC ANEMIA (23-28)
    (v_topic_id, 'Sideroblastic anemia is defined by ring sideroblasts on bone marrow biopsy. What are ring sideroblasts?', '["RBCs with iron deposits on the outer membrane", "Erythroblasts with iron-laden mitochondria arranged in a perinuclear ring on Prussian blue stain", "Neutrophils with iron granules", "Macrophages engulfing iron-rich debris"]', 1, 'Ring sideroblasts = nucleated RBC precursors (erythroblasts) with iron-loaded mitochondria staining as a blue ring around the nucleus on Prussian blue stain. They are pathognomonic of sideroblastic anemia.'),
    (v_topic_id, 'The most common cause of acquired sideroblastic anemia is?', '["Lead poisoning", "Isoniazid therapy", "Alcohol use", "Copper deficiency"]', 2, 'Alcohol is the most common acquired cause. It is mitochondrially toxic and also antagonizes B6 (pyridoxal phosphate), which is the obligate cofactor for ALA synthase — the first enzyme in heme synthesis.'),
    (v_topic_id, 'Isoniazid (INH) causes sideroblastic anemia by what mechanism?', '["Direct inhibition of ferrochelatase", "Antagonizing pyridoxine (B6), the cofactor for ALA synthase, impairing heme synthesis", "Blocking iron absorption in the duodenum", "Causing autoimmune destruction of erythroid precursors"]', 1, 'INH is a structural analogue of B6 and competes with it. Without B6, ALA synthase (the rate-limiting enzyme in heme synthesis) cannot function, leading to iron accumulation in mitochondria and ring sideroblasts.'),
    (v_topic_id, 'Lead poisoning inhibits which two enzymes in the heme synthesis pathway, causing sideroblastic anemia?', '["ALA synthase and ferrochelatase", "ALA dehydratase and ferrochelatase", "Uroporphyrinogen decarboxylase and ferrochelatase", "ALA synthase and uroporphyrinogen synthase"]', 1, 'Lead inhibits ALA dehydratase (second enzyme) and ferrochelatase (last enzyme, inserts Fe2+ into protoporphyrin IX). This causes accumulation of ALA in urine and coarse basophilic stippling of RBCs on smear.'),
    (v_topic_id, 'A child with lead poisoning has basophilic stippling of RBCs. What is the source of these stippled deposits?', '["Iron granules in mitochondria", "Aggregated ribosomes (lead inhibits pyrimidine 5-nucleotidase, preventing ribosomal RNA degradation)", "Heinz bodies", "Howell-Jolly bodies"]', 1, 'Lead inhibits pyrimidine 5-nucleotidase, blocking breakdown of ribosomal RNA in maturing RBCs. Undegraded ribosomal RNA aggregates appear as coarse basophilic stippling on Wright-Giemsa stain.'),
    (v_topic_id, 'Which combination of lab findings is characteristic of sideroblastic anemia?', '["Low serum iron, high TIBC, low ferritin", "High serum iron, high ferritin, low TIBC, ring sideroblasts on marrow biopsy", "Low serum iron, low ferritin, ring sideroblasts", "Normal serum iron, elevated TIBC, ring sideroblasts"]', 1, 'In sideroblastic anemia, iron enters cells normally but cannot be incorporated into heme. Iron accumulates in serum and tissues: high serum iron + high ferritin + low TIBC (iron overloaded, no need for more transferrin) + ring sideroblasts.'),

    -- ALPHA THALASSEMIA (29-35)
    (v_topic_id, 'Alpha-thalassemia results from deletion of alpha-globin genes (normally 4 copies, 2 per chromosome 16). Deletion of all four genes (-- /--) causes?', '["Alpha-thalassemia silent trait with no symptoms", "Hemoglobin H disease with moderate hemolysis", "Hydrops fetalis and intrauterine death due to hemoglobin Barts", "Beta-thalassemia major"]', 2, 'With all 4 alpha genes deleted, no alpha chains are made. The fetus produces Hgb Barts (gamma4 tetramers) which has near-irreversible O2 affinity and cannot deliver oxygen to tissues, causing fatal hydrops fetalis.'),
    (v_topic_id, 'Deletion of THREE alpha-globin genes causes HbH disease. What is hemoglobin H composed of?', '["4 gamma chains", "4 beta chains (beta-4 tetramers)", "2 alpha and 2 delta chains", "2 beta and 2 gamma chains"]', 1, 'With only 1 functional alpha gene, excess beta chains form HbH (beta4). HbH is unstable, precipitates in RBCs forming inclusion bodies, causing moderate chronic hemolytic anemia.'),
    (v_topic_id, 'Deletion of TWO alpha-globin genes in CIS (-- /aa) vs. in TRANS (a-/a-): which configuration is more clinically dangerous for offspring?', '["Trans (a-/a-) is more dangerous", "Cis (-- /aa) is more dangerous because both deletions are on the same chromosome, allowing offspring to potentially inherit all 4 deletions (-- /--)", "Both configurations are equally dangerous", "Neither poses a risk to offspring"]', 1, 'The cis configuration (both deletions on one chromosome 16) is dangerous in populations. If two cis carriers mate, offspring can inherit (-- /--) = hydrops fetalis. Common in Southeast Asian populations.'),
    (v_topic_id, 'Which of the following is the characteristic finding on hemoglobin electrophoresis in a patient with alpha-thalassemia trait (2-gene deletion)?', '["Elevated HbA2 (>3.5%)", "Elevated HbF", "Completely normal electrophoresis", "Presence of HbH"]', 2, 'Alpha-thal trait has a NORMAL electrophoresis, unlike beta-thal minor (elevated HbA2). The only clues are mild microcytosis, normal iron studies, and family origin (Southeast Asian or African). This is a critical distinction.'),
    (v_topic_id, 'A Southeast Asian woman has unexplained mild microcytosis (MCV 72). Serum iron, TIBC, and ferritin are all normal. Hemoglobin electrophoresis is normal. What is the likely diagnosis?', '["Iron deficiency anemia", "Beta-thalassemia minor", "Alpha-thalassemia trait (2-gene deletion)", "Anemia of chronic disease"]', 2, 'Alpha-thalassemia trait: mild microcytosis + normal iron studies + NORMAL electrophoresis. Beta-thal minor would show elevated HbA2. IDA would show low ferritin. Ethnicity (Southeast Asian, African) is a major clue.'),
    (v_topic_id, 'In hemoglobin Barts (seen in hydrops fetalis due to 4-gene alpha deletion), why is oxygen delivery to tissues impossible?', '["Hgb Barts has no iron-containing heme groups", "Hgb Barts (gamma4 tetramers) has near-irreversible O2 affinity with no cooperativity or Bohr effect, so O2 cannot be released to tissues", "Hgb Barts precipitates immediately upon leaving the lung", "Hgb Barts has reduced O2 binding capacity"]', 1, 'Gamma4 tetramers have an oxygen dissociation curve shifted so far left (extreme O2 affinity) that oxygen is never offloaded at the tissue level. This is analogous to carbon monoxide poisoning but intrinsic to the molecule.'),
    (v_topic_id, 'In which ethnic groups is alpha-thalassemia most prevalent?', '["Mediterranean (Italian, Greek) populations", "Southeast Asian and African populations", "Northern European populations", "Middle Eastern populations exclusively"]', 1, 'Alpha-thalassemia is most common in Southeast Asia (where cis deletions predominate, causing risk of hydrops fetalis) and sub-Saharan Africa (where trans deletions are more common, limiting severity). Beta-thal is more common in Mediterranean.'),

    -- BETA THALASSEMIA (36-40)
    (v_topic_id, 'Beta-thalassemia major (Cooley anemia) presents after 6 months of age. Why not at birth?', '["Iron stores are sufficient at birth", "HbF (alpha2/gamma2) is the predominant hemoglobin at birth and does not require beta chains; symptoms emerge as HbF is replaced by HbA (which requires beta chains)", "The spleen is not yet developed", "Beta-globin gene expression is suppressed by maternal hormones"]', 1, 'HbF dominates at birth and does not need beta chains. By 6 months, gamma chain production normally declines and beta chain production increases. In beta0/beta0 patients, this switch reveals the fatal beta chain deficit.'),
    (v_topic_id, 'A 1-year-old child from a Greek family has severe anemia (Hgb 4), marked hepatosplenomegaly, frontal bossing, and a skull X-ray showing hair-on-end pattern. Diagnosis?', '["Alpha-thalassemia major (hydrops fetalis)", "Beta-thalassemia major (Cooley anemia)", "Sickle cell disease", "Hereditary spherocytosis"]', 1, 'Beta-thal major: severe transfusion-dependent anemia + hepatosplenomegaly (extramedullary hematopoiesis) + hair-on-end skull X-ray (marrow expansion into diploe) + frontal bossing + chipmunk facies from maxillary expansion.'),
    (v_topic_id, 'The hair-on-end skull X-ray in beta-thalassemia major is caused by?', '["Iron deposition in the skull diploe", "Dramatic expansion of the bone marrow cavity into the skull diploe as the marrow tries to compensate for severe anemia", "Subperiosteal hemorrhage", "Vitamin D deficiency causing rickets"]', 1, 'Marrow expands aggressively (extramedullary and intramedullary hematopoiesis) to compensate for the severe anemia. The skull diploe widens and the trabeculae are pushed perpendicular to the inner table, creating the hair-on-end or crew-cut pattern.'),
    (v_topic_id, 'Beta-thalassemia major patients develop iron overload even before multiple transfusions. Why?', '["Increased renal iron reabsorption", "Ineffective erythropoiesis suppresses hepcidin (via GDF15), dramatically increasing intestinal iron absorption", "Increased dietary iron intake", "Decreased hepcidin production from liver failure"]', 1, 'The massively expanded but ineffective erythroid activity releases GDF15, which suppresses hepcidin. Low hepcidin = ferroportin is not degraded = maximum iron absorption from the gut. Iron overload (hemochromatosis) damages heart, liver, and endocrine organs.'),
    (v_topic_id, 'What is the characteristic hemoglobin electrophoresis finding in beta-thalassemia MINOR (trait)?', '["Elevated HbS (>50%)", "Elevated HbA2 (>3.5%) and often mildly elevated HbF", "Completely normal electrophoresis", "Absent HbA, all HbF"]', 1, 'In beta-thal minor (one defective beta gene), delta chain production compensates, raising HbA2 above 3.5% (normal <3.5%). This is the single most important diagnostic finding. Distinguishes it from alpha-thal trait (normal electrophoresis).')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
